overrides.update({832+i:t+'.' for i,t in enumerate(tail)})
for i,item in enumerate(items):
    text=overrides.get(i,item['text'])
    if i not in overrides:
        for a,b in [('Watch ','Look at '),("I'm looking for ",'Find '),('Put on ','Place '),('Put right on ','Tick '),('Put right ','Tick '),('Put it right on ','Tick '),('Put a mark on ','Tick '),('Put a mark ','Tick '),('baby','child'),('kid','child'),('escorts','grown-ups'),('escort','grown-up'),('facilities','your grown-up'),('facilitates','your grown-up'),('husband','pair'),('couples','pairs'),('circuits','circles'),('ribs','sides'),('base of','rule for'),('base.','rule.'),('normal things','natural things'),('next to him','next to it'),('next to her','next to it'),('his color','its color'),('her group','its group')]:text=text.replace(a,b)
    item['text']=text.strip()
    assert item['text'] and not re.search('[\u0600-\u06ff]',item['text']),i
data['review']='Authored shared instructions, vocabulary and domain corrections; English text reviewed before synthesis.'
